package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// EmpRec 01 EMP-REC, 17 bytes
type EmpRec struct {
	ErId   string          // PIC X(5) @0 len=5
	ErDept string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string          // PIC X len=1 = "N"
var WsFirstFlag string        // PIC X len=1 = "Y"
var WsPrevDept string         // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal   // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64          // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64          // PIC 9(5) len=5 = 0
var WsHoursEd string          // PIC ZZ9.9 len=5
var WsRateEd string           // PIC ZZ9.99 len=6
var WsGrossEd string          // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string           // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string          // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var empRec EmpRec

// file handling
var empFile *os.File
var empScanner *bufio.Scanner
var empEof bool

func initValues() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = "   "
	WsRegHours = decimal.NewFromInt(0)
	WsOtHours = decimal.NewFromInt(0)
	WsGross = decimal.NewFromInt(0)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
	WsGrandTotal = decimal.NewFromInt(0)
	WsGrandCount = 0
	WsHoursEd = ""
	WsRateEd = ""
	WsGrossEd = ""
	WsDeptEd = ""
	WsGrandEd = ""
	empRec = EmpRec{
		ErId:    "     ",
		ErDept:  "   ",
		ErHours: decimal.NewFromInt(0),
		ErRate:  decimal.NewFromInt(0),
	}
	empEof = false
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseNumField(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s contains only digits (maybe with leading zeros)
	// Use decimal.NewFromString then shift?
	// The COBOL display stores digits only, implied decimal.
	// So integer value of s divided by 10^scale.
	// Parse as integer.
	d, err := decimal.NewFromString(s)
	if err != nil {
		// fallback: treat non-digit as 0
		d = decimal.NewFromInt(0)
	}
	if scale != 0 {
		d = d.Shift(-scale)
	}
	return d
}

func formatEdited(value decimal.Decimal, picture string) string {
	// split picture into integer part and fraction part
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := len(fracPic) // all 9s
	// count int digit slots
	intDigitCount := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigitCount++
		}
	}
	// Round value to fracDigits (half away)
	scaledVal := value.Round(int32(fracDigits))
	// Get string fixed
	fixed := scaledVal.StringFixed(int32(fracDigits))
	// fixed may be "-xxx.yy" but values are non-negative
	// Split
	var intPartStr, fracPartStr string
	if dotIdx >= 0 {
		parts := strings.SplitN(fixed, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", fracDigits)
		}
	} else {
		intPartStr = fixed
		fracPartStr = ""
	}
	// handle sign: not needed (values >=0), but strip '-'
	if strings.HasPrefix(intPartStr, "-") {
		intPartStr = intPartStr[1:]
	}
	if strings.HasPrefix(intPartStr, "+") {
		intPartStr = intPartStr[1:]
	}
	// pad or truncate high-order digits
	if len(intPartStr) < intDigitCount {
		intPartStr = strings.Repeat("0", intDigitCount-len(intPartStr)) + intPartStr
	} else if len(intPartStr) > intDigitCount {
		intPartStr = intPartStr[len(intPartStr)-intDigitCount:]
	}
	// Ensure fracPartStr length
	if len(fracPartStr) < fracDigits {
		fracPartStr = fracPartStr + strings.Repeat("0", fracDigits-len(fracPartStr))
	} else if len(fracPartStr) > fracDigits {
		fracPartStr = fracPartStr[:fracDigits]
	}

	// Build output
	// intPart output array size len(intPic)
	intOut := make([]rune, len(intPic))
	for i, ch := range intPic {
		intOut[i] = ch
	}
	// Map digits onto Z/9 positions
	digitIdx := 0
	// Need to know suppression state
	suppressActive := true
	// We will fill intOut in order
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := rune(intPartStr[digitIdx])
			digitIdx++
			if ch == 'Z' && suppressActive && d == '0' {
				// Check if this is the last integer digit and all digits were zero?
				// For COBOL, if all digits are zero, the last '9' ensures a zero is printed.
				// Our logic: Z with zero while suppressing => space, keep suppressActive.
				intOut[i] = ' '
				// keep suppressActive true
			} else {
				intOut[i] = d
				suppressActive = false
			}
		} else if ch == ',' {
			if suppressActive {
				intOut[i] = ' '
			} else {
				intOut[i] = ','
			}
		} else {
			// should not happen for intPic
			intOut[i] = ch
		}
	}

	// Combine
	if dotIdx >= 0 {
		// picture includes dot, total length = len(picture)
		// Build final string: intOut + "." + fracPartStr
		result := string(intOut) + "." + fracPartStr
		// result length must equal len(picture)
		// Ensure exactly picture length (should be)
		if len(result) != len(picture) {
			// adjust (should not happen)
			if len(result) < len(picture) {
				result = strings.Repeat(" ", len(picture)-len(result)) + result
			} else {
				result = result[len(result)-len(picture):]
			}
		}
		return result
	}
	return string(intOut)
}

func formatIntPadded(v int64, width int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > width {
		// high-order truncated? For integer DISPLAY, spec says numeric-edited drops high, but for unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded to its digit count. What about overflow? Likely also truncate high-order? But spec says numeric field truncates high-order on store. For display we just show low-order digits zero-padded.
		// Keep low-order width digits
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

// store simulation for numeric fields with truncation to picture size
// ForWsGross PIC 9(7)V99 => integer digits 7, scale 2, total digits 9
// We need to simulate low-order truncation on store.
// Generic store: keep only low-order n digits of integer representation?
func storeNumeric(value decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate (not round) to scale unless ROUNDED is used; for ROUNDED we already rounded.
	// Then keep low-order digits.
	// Compute scaled integer = value * 10^scale truncated toward zero
	// Use Truncate(scale)
	truncated := value.Truncate(scale)
	// Get scaled integer
	scaled := truncated.Shift(scale).Truncate(0) // integer
	// Determine modulus = 10^(intDigits+scale)
	// To keep low-order digits, we can do modulo 10^n where n = total digits
	totalDigits := intDigits + int(scale)
	// modulus = 10^totalDigits
	mod := decimal.New(1, int32(totalDigits)) // 10^n
	// For positive values, low-order = scaled mod mod
	// For negative, need preserve sign? Values are positive in this program.
	if scaled.Sign() < 0 {
		neg := scaled.Neg()
		low := neg.Mod(*mod)
		scaled = low.Neg()
	} else {
		scaled = scaled.Mod(*mod)
	}
	// Convert back
	result := scaled.Shift(-scale)
	return result
}

func isFirstRecord() bool {
	return WsFirstFlag == "Y"
}
func isInputDone() bool {
	return WsEofFlag == "Y"
}

// Paragraphs

func MainPara() {
	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		// If file not exists, treat as empty? COBOL would error, but we create empty scanner
		empScanner = bufio.NewScanner(strings.NewReader(""))
		empEof = true
	} else {
		defer empFile.Close()
		empScanner = bufio.NewScanner(empFile)
		// Allow long lines
		empScanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
		ReadPara()
		for !isInputDone() {
			ProcessPara()
		}
		if !isFirstRecord() {
			DeptBreakPara()
		}
		// close handled by defer
		GrandPara()
		return
	}
	// no file case
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	GrandPara()
}

func ReadPara() {
	if empScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !empScanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := empScanner.Text()
	// Pad with spaces to record length 17
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	// Parse fields by offset
	erId := line[0:5]
	erDept := line[5:8]
	erHoursStr := line[8:12]
	erRateStr := line[12:17]
	empRec.ErId = erId
	empRec.ErDept = erDept
	empRec.ErHours = parseNumField(erHoursStr, 1)
	empRec.ErRate = parseNumField(erRateStr, 2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = empRec.ErDept
		WsFirstFlag = "N"
	} else {
		if empRec.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = empRec.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	// EVALUATE TRUE
	if empRec.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = decimal.NewFromInt(40)
		WsOtHours = empRec.ErHours.Sub(decimal.NewFromInt(40))
	} else {
		WsRegHours = empRec.ErHours
		WsOtHours = decimal.NewFromInt(0)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE * 1.5
	onePointFive := decimal.NewFromFloat(1.5) // exactly 1.5
	rawGross := WsRegHours.Mul(empRec.ErRate).Add(WsOtHours.Mul(empRec.ErRate).Mul(onePointFive))
	// ROUNDED to scale of WsGross (2)
	rounded := rawGross.Round(2)
	WsGross = storeNumeric(rounded, 7, 2)
	// ADD WS-GROSS TO WS-DEPT-TOTAL
	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptTotal = storeNumeric(WsDeptTotal, 9, 2)
	// ADD 1 TO WS-DEPT-COUNT (PIC 9(3))
	WsDeptCount = (WsDeptCount + 1) % 1000 // low-order 3 digits (mod 1000)
	// ADD WS-GROSS TO WS-GRAND-TOTAL
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandTotal = storeNumeric(WsGrandTotal, 11, 2)
	// ADD 1 TO WS-GRAND-COUNT
	WsGrandCount = (WsGrandCount + 1) % 100000 // mod 100000

	WsHoursEd = formatEdited(WsRegHours.Add(WsOtHours), "ZZ9.9") // Actually ER-HOURS value
	// But spec: MOVE ER-HOURS TO WS-HOURS-ED . So use empRec.ErHours directly
	WsHoursEd = formatEdited(empRec.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(empRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED
	// ER-ID and ER-DEPT are X fields exactly as stored (5 and 3 chars)
	fmt.Printf("%s %s %s %s %s\n", empRec.ErId, empRec.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatIntPadded(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatIntPadded(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

func main() {
	initValues()
	MainPara()
}

